const rule = $input.item.json;
const entities = rule.entities || [];
if (entities.length === 0) return [{ json: { skip: true, reason: 'No entities', rule } }];
const token = entities[0]?.token || null;
if (!token) return [{ json: { skip: true, reason: 'No token', rule } }];
const MAX = 24;
const chunks = [];

if (rule.scope === 'account' && entities.length > 0 && entities.every(e => e.entityId.startsWith('act_'))) {
  for (let i = 0; i < entities.length; i += MAX) {
    const chunk = entities.slice(i, i + MAX);
    const batch = chunk.map(e => ({ method: 'GET', relative_url: `${e.entityId}/insights?date_preset=today&fields=spend` }));
    chunks.push({ json: { batch, token, rule, entities, chunkIndex: chunks.length, isAccountScope: true } });
  }
  return chunks;
}

for (let i = 0; i < entities.length; i += MAX) {
  const chunk = entities.slice(i, i + MAX);
  const batch = [
    ...chunk.map(e => ({ method: 'GET', relative_url: `${e.entityId}?fields=effective_status,name` })),
    ...chunk.map(e => ({ method: 'GET', relative_url: `${e.entityId}/insights?fields=spend,actions,action_values,purchase_roas,cost_per_action_type&date_preset=today` })),
  ];
  chunks.push({ json: { batch, token, rule, entities, chunkIndex: chunks.length } });
}
return chunks;

const { entities, rule, fbResponses, isAccountScope } = $input.item.json;
const responses = fbResponses || [];
const n = entities.length;
const snapshots = entities.map((e, i) => {
  let spend = 0;
  const resp = isAccountScope ? responses[i] : responses[n + i];
  if (resp && resp.code === 200) {
    try { const b = JSON.parse(resp.body); spend = parseFloat(b?.data?.[0]?.spend || 0); } catch {}
  }
  return { entity_id: e.entityId, entity_type: rule.scope, spend };
});
return [{ json: { snapshots, entity_ids: entities.map(e => e.entityId), _passthrough: $input.item.json } }];

const burstData_1h = $input.item.json;
const burstData = $('Check Burst').item.json;
const passthrough = $('Prepare Snapshots').item.json._passthrough;
return [{ json: { ...passthrough, burstData, burstData_1h } }];

const { rule, entities, token, fbResponses, burstData: burstDataRaw, burstData_1h: burstDataRaw1h } = $input.item.json;
const responses = fbResponses || [];
const burstData = burstDataRaw || {};
const burstData_1h = burstDataRaw1h || {};
const n = entities.length;

function parseInsights(resp, rt) {
  if (!resp || resp.code !== 200) return null;
  let body; try { body = JSON.parse(resp.body); } catch { return null; }
  const d = body?.data?.[0];
  if (!d) return null;
  const spend = parseFloat(d.spend || 0);
  const fbConversions = parseFloat(d.actions?.find(a => a.action_type === 'purchase')?.value || 0);
  const conversions = rt ? (rt.conversions || 0) : fbConversions;
  const cpa = conversions > 0 ? spend / conversions : 0;
  const roas = parseFloat(d.purchase_roas?.[0]?.value || 0);
  const purchaseValue = parseFloat(d.action_values?.find(a => a.action_type === 'purchase')?.value || 0);
  const roi = rt ? (rt.roi || 0) : (spend > 0 ? (purchaseValue - spend) / spend : 0);
  const revenue = rt ? (rt.revenue || 0) : purchaseValue;
  const profit = rt ? (rt.profit || 0) : (purchaseValue - spend);
  return { spend_today: spend, conversions, cpa, roas, roi, revenue, profit };
}

const conditions = rule.conditions || [];
const combinator = rule.combinator || 'AND';
const triggered = [];

for (let i = 0; i < n; i++) {
  const entity = entities[i];
  const entityId = entity.entityId;
  const entityToken = entity.token || token;

  const statusResp = responses[i];
  let entityName = entityId;
  if (statusResp?.code === 200) {
    let sb; try { sb = typeof statusResp.body === 'string' ? JSON.parse(statusResp.body) : statusResp.body; } catch {}
    entityName = sb?.name || entity.entityName || entityId;
    if (sb?.effective_status === 'PAUSED' && rule.action !== 'enable') continue;
  }

  const todayInsights = parseInsights(responses[n + i], entity.rt);
  const insights3d = entity.insights_3d || null;
  const insights7d = entity.insights_7d || null;
  if (!todayInsights) continue;

  const burst = burstData[entityId] || {};
  const burstMetrics = { burst_multiplier: burst.burst_multiplier || 0, spend_30m: burst.spend_recent || 0, avg_30m: burst.avg_period || 0 };
  const burst1h = burstData_1h[entityId] || {};
  const burstMetrics1h = { burst_multiplier: burst1h.burst_multiplier || 0, spend_1h: burst1h.spend_recent || 0, avg_1h: burst1h.avg_period || 0 };

  const evaluate = (c) => {
    if (c.lookback === 'last_30m') {
      const val = burstMetrics[c.metric];
      if (val === undefined || val === null) return false;
      switch (c.operator) {
        case 'gt': return val > c.value;
        case 'lt': return val < c.value;
        case 'gte': return val >= c.value;
        case 'lte': return val <= c.value;
        case 'eq': return val === c.value;
        default: return false;
      }
    }
    if (c.lookback === 'last_1h') {
      const val = burstMetrics1h[c.metric];
      if (val === undefined || val === null) return false;
      switch (c.operator) {
        case 'gt': return val > c.value;
        case 'lt': return val < c.value;
        case 'gte': return val >= c.value;
        case 'lte': return val <= c.value;
        case 'eq': return val === c.value;
        default: return false;
      }
    }
    const src = c.lookback === 'last_7d' ? insights7d : c.lookback === 'last_3d' ? insights3d : todayInsights;
    const val = src?.[c.metric];
    if (val === undefined || val === null) return false;
    switch (c.operator) {
      case 'gt':  return val > c.value;
      case 'lt':  return val < c.value;
      case 'gte': return val >= c.value;
      case 'lte': return val <= c.value;
      case 'eq':  return val === c.value;
      default:    return false;
    }
  };

  const allMet = combinator === 'OR' ? conditions.some(evaluate) : conditions.every(evaluate);
  if (allMet) {
    triggered.push({ json: { rule, entityId, entityName, metrics: { ...todayInsights, ...burstMetrics }, token: entityToken } });
  }
}

if (rule.scope === 'account' && conditions.length > 0) {
  const isAcct = !!$input.item.json.isAccountScope;
  if (isAcct) {
    const totalSpend = entities.reduce((sum, e, i) => {
      const resp = responses[i];
      if (!resp || resp.code !== 200) return sum;
      let body; try { body = JSON.parse(resp.body); } catch { return sum; }
      return sum + parseFloat(body?.data?.[0]?.spend || 0);
    }, 0);
    const condition = conditions[0];
    if (condition && totalSpend > condition.value) {
      const campaignItems = [];
      for (const e of entities) {
        const campaignIds = e.campaignIds || [];
        for (const cid of campaignIds) {
          campaignItems.push({ json: { rule, entityId: String(cid), entityName: (`Campaign ${cid} (Acct ${e.entityId})`), metrics: { spend_today: totalSpend, account_spend_today: totalSpend }, token: e.token || token } });
        }
      }
      if (campaignItems.length > 0) return campaignItems;
      return [{ json: { noTrigger: true } }];
    }
    return [{ json: { noTrigger: true } }];
  }
  const totalSpend = entities.reduce((sum, e, i) => {
    const ins = parseInsights(responses[n + i]);
    return sum + (ins?.spend_today || 0);
  }, 0);
  const condition = conditions[0];
  if (condition && totalSpend > condition.value) {
    return entities.map((e, i) => {
      let entityName = e.entityId;
      const statusResp = responses[i];
      if (statusResp?.code === 200) {
        try { entityName = JSON.parse(statusResp.body)?.name || e.entityId; } catch {}
      }
      const ins = parseInsights(responses[n + i]) || { spend_today: 0 };
      return { json: { rule, entityId: e.entityId, entityName, metrics: { spend_today: ins.spend_today, account_spend_today: totalSpend }, token: e.token || token } };
    });
  }
  return [{ json: { noTrigger: true } }];
}

return triggered.length > 0 ? triggered : [{ json: { noTrigger: true } }];

const d = $input.item.json;
return [{ json: {
  rule_id: d.rule.id,
  entity_type: d.rule.scope,
  entity_id: d.entityId,
  entity_name: d.entityName || d.entityId,
  action_taken: 'would_have_' + d.rule.action + 'd',
  trigger_data_json: JSON.stringify(d.metrics),
  is_dry_run: 1
} }];

const d = $input.item.json;
const m = d.metrics;
const name = d.entityName || d.entityId;
const time = new Date().toLocaleTimeString('en-US', {timeZone: 'America/New_York', hour: 'numeric', minute: '2-digit'}) + ' ET';
const isBurst = (d.rule.conditions || []).some(c => c.lookback === 'last_30m');
let text;
if (isBurst) {
  const burst = d.burstMetrics || {};
  const pct = ((burst.burst_multiplier || 0) * 100).toFixed(0);
  text = '🧪 *[DRY RUN]* 💥 ' + d.rule.name + '\n`' + name + '`  |  would PAUSE\nLast 30 min: $' + (burst.spend_30m || 0).toFixed(0) + ' spent (normal: $' + (burst.avg_30m || 0).toFixed(0) + ') — ' + pct + '%\n' + time;
} else {
  const roi = m.roi != null ? ((m.roi * 100).toFixed(1) + '%') : 'N/A';
  const cpa = m.cpa != null ? ('$' + m.cpa.toFixed(0)) : 'N/A';
  text = '🧪 *[DRY RUN]* ' + d.rule.name + '\n`' + name + '`  |  would ' + d.rule.action.toUpperCase() + '\nSpend: $' + m.spend_today.toFixed(0) + '  |  ROI: ' + roi + '  |  CPA: ' + cpa + '\n' + time;
}
const reply_markup = JSON.stringify({ inline_keyboard: [[{ text: '💤 Snooze 6h', callback_data: 'snooze:' + d.rule.id + ':' + d.entityId }]] });
return [{ json: { chat_id: $env.TELEGRAM_CHAT_ID, text, parse_mode: 'Markdown', reply_markup } }];

const { rule, entityId, entityName, metrics, token } = $input.item.json;

let body = {};
if (rule.action === 'pause') body = { status: 'PAUSED', access_token: token };
else if (rule.action === 'enable') body = { status: 'ACTIVE', access_token: token };

return [{ json: { entityId, entityName, body, rule, metrics, token } }];

const { entityId, entityName, rule, metrics, token, daily_budget } = $input.item.json;
const currentBudgetCents = parseInt(daily_budget || 0);
const scaledCents = Math.round(currentBudgetCents * 1.2);
const maxCents = rule.action_params?.max_budget ? rule.action_params.max_budget * 100 : Infinity;
const newBudgetCents = Math.min(scaledCents, maxCents);
const noAction = newBudgetCents === currentBudgetCents;
return [{ json: { entityId, entityName, rule, metrics, token, newBudgetCents, noAction } }];

const d = $('Evaluate Rules').item.json;
const fbResult = $input.item.json;
return [{ json: { ...d, fbResult, actionFailed: !!(fbResult?.error || fbResult?.message) } }];

const d = $('Evaluate Rules').item.json;
const fbResult = $input.item.json;
return [{ json: { ...d, fbResult, actionFailed: !!(fbResult?.error || fbResult?.message) } }];

const d = $('Evaluate Rules').item.json;
const actionFailed = !!$('Restore After FB API').item.json.actionFailed;
return [{ json: { ...d, actionFailed } }];

const d = $input.item.json;
const m = d.metrics;
const name = d.entityName || d.entityId;
const time = new Date().toLocaleTimeString('en-US', {timeZone: 'America/New_York', hour: 'numeric', minute: '2-digit'}) + ' ET';
const isBurst = (d.rule.conditions || []).some(c => c.lookback === 'last_30m');
let text;
if (isBurst) {
  const burst = d.burstMetrics || {};
  const pct = ((burst.burst_multiplier || 0) * 100).toFixed(0);
  text = '💥 *Velocity Kill: ' + d.rule.name + '*\n`' + name + '`  |  PAUSED\nLast 30 min: $' + (burst.spend_30m || 0).toFixed(0) + ' spent (normal: $' + (burst.avg_30m || 0).toFixed(0) + ') — ' + pct + '%\n' + time;
} else {
  const roi = m.roi != null ? ((m.roi * 100).toFixed(1) + '%') : 'N/A';
  const cpa = m.cpa != null ? ('$' + m.cpa.toFixed(0)) : 'N/A';
  text = '🛑 *' + d.rule.action.charAt(0).toUpperCase() + d.rule.action.slice(1) + ': ' + d.rule.name + '*\n`' + name + '`  |  ' + d.rule.action.toUpperCase() + 'D\nSpend: $' + m.spend_today.toFixed(0) + '  |  ROI: ' + roi + '  |  CPA: ' + cpa + '\n' + time;
}
const reply_markup = JSON.stringify({ inline_keyboard: [[{ text: '✅ Re-enable', callback_data: 'reenable:' + d.rule.id + ':' + d.entityId }, { text: '💤 Snooze 6h', callback_data: 'snooze:' + d.rule.id + ':' + d.entityId }]] });
return [{ json: { chat_id: $env.TELEGRAM_CHAT_ID, text, parse_mode: 'Markdown', reply_markup } }];

const d = $('Evaluate Rules').item.json;
let actionFailed = false;
try { actionFailed = !!$('Restore After FB API').item.json.actionFailed; } catch(e) {}
try { if (!actionFailed) actionFailed = !!$('Restore After Scale').item.json.actionFailed; } catch(e) {}
return [{ json: {
  rule_id: d.rule.id,
  entity_type: d.rule.scope,
  entity_id: d.entityId,
  entity_name: d.entityName || d.entityId,
  action_taken: actionFailed ? d.rule.action + '_failed' : d.rule.action + 'd',
  trigger_data_json: JSON.stringify(d.metrics),
  is_dry_run: 0
} }];

const d = $('Evaluate Rules').item.json;
let entityId = d.entityId;
if (d.rule.scope === 'account') {
  const m = (d.entityName || '').match(/\(Acct (act_\d+)\)/);
  if (m) entityId = m[1];
}
return [{ json: { rule_id: d.rule.id, entity_id: entityId, type: 'cooldown', cooldown_hours: d.rule.cooldown_hours || 4 } }];

const chunkMeta = $('Build FB Batch').item.json;
const fbItems = $input.all();
const chunkResponses = fbItems.map(i => i.json);
return [{ json: {
  rule: chunkMeta.rule,
  entities: chunkMeta.entities,
  token: chunkMeta.token,
  chunkIndex: chunkMeta.chunkIndex,
  isAccountScope: chunkMeta.isAccountScope || false,
  chunkResponses,
}}];

const items = $input.all();
const first = items[0].json;
const allResponses = items.flatMap(i => i.json.chunkResponses || []);
return [{ json: {
  rule: first.rule,
  entities: first.entities,
  fbResponses: allResponses,
  token: first.token,
  isAccountScope: first.isAccountScope || false,
}}];

const d = $input.item.json;
const responses = d.fbResponses || [];
const successCount = responses.filter(r => r && r.code === 200).length;
const pullOk = responses.length > 0 && successCount > 0;
return [{ json: { ...d, pullOk } }];

const d = $('Evaluate Rules').item.json;
let entityId = d.entityId;
if (d.rule.scope === 'account') {
  const m = (d.entityName || '').match(/\(Acct (act_\d+)\)/);
  if (m) entityId = m[1];
}
return [{ json: { rule_id: d.rule.id, entity_id: entityId, type: 'cooldown', cooldown_hours: 0.5 } }];

const { entities, fbResponses } = $input.item.json;
const n = entities.length;
const names = [];
for (let i = 0; i < n; i++) {
  const resp = fbResponses[i];
  if (!resp || resp.code !== 200) continue;
  let body;
  try { body = JSON.parse(resp.body); } catch { continue; }
  if (body.name) names.push({ id: entities[i].entityId, name: body.name });
}
return [{ json: { names } }];

const items = $input.all().map(i => i.json);
return [{ json: {
  items: items.map(i => ({ rule_id: i.rule.id, entity_id: i.entityId })),
  _context: items,
} }];

const { results, _context } = $input.item.json;
const pendingMap = Object.fromEntries((results || []).map(r => [String(r.entity_id), r.pending]));
return (_context || []).map(item => ({
  json: { ...item, pending: pendingMap[String(item.entityId)] || false }
}));

const items = $input.all().map(i => i.json);
return [{ json: {
  items: items.map(i => {
    let entityId = i.entityId;
    if (i.rule && i.rule.scope === 'account') {
      const m = (i.entityName || '').match(/\(Acct (act_\d+)\)/);
      if (m) entityId = m[1];
    }
    return { rule_id: i.rule.id, entity_id: entityId };
  }),
  _context: items,
} }];

const { results, _context } = $input.item.json;
const exemptMap = Object.fromEntries((results || []).map(r => [`${r.rule_id}:${String(r.entity_id)}`, r.exempt]));
return (_context || []).map(item => {
  let lookupId = item.entityId;
  if (item.rule && item.rule.scope === 'account') {
    const m = (item.entityName || '').match(/\(Acct (act_\d+)\)/);
    if (m) lookupId = m[1];
  }
  return { json: { ...item, exempt: exemptMap[`${item.rule.id}:${String(lookupId)}`] || false } };
});
